$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$migration = Decode ""

$migrationPath = Join-Path $root "supabase\migrations\20260812223200_klyx_group_atomic_live_coverage_12_96.sql"
$groupRoutePath = Join-Path $root "app\api\market\requests\[id]\group-booking\route.ts"
$liveHelperPath = Join-Path $root "lib\multi-slot-live-coverage.ts"

if (-not (Test-Path -LiteralPath $groupRoutePath)) {
    throw "12.96 : route group-booking 12.85 introuvable."
}

if (-not (Test-Path -LiteralPath $liveHelperPath)) {
    throw "12.96 : helper live 12.95 introuvable."
}

$groupRoute = [System.IO.File]::ReadAllText($groupRoutePath)
$liveHelper = [System.IO.File]::ReadAllText($liveHelperPath)

if (-not ($groupRoute.Contains("KLYX_GROUP_BOOKING_CREATE_12_85") -or $groupRoute.Contains("klyx_create_multi_slot_booking_group"))) {
    throw "12.96 : architecture group booking 12.85 introuvable."
}

if (-not $liveHelper.Contains("KLYX_MULTI_SLOT_LIVE_COVERAGE_12_95")) {
    throw "12.96 : revalidation live 12.95 introuvable."
}

New-Item -ItemType Directory -Force -Path (Split-Path -Parent $migrationPath) | Out-Null

[System.IO.File]::WriteAllText($migrationPath, $migration, $utf8)

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 12.96 PREPARE"
Write-Host "======================================"
Write-Host "Revalidation DB atomique : PRETE"
Write-Host "Disponibilites live : VERIFIEES"
Write-Host "Conflits accepted/completed : VERIFIES"
Write-Host "Planning change apres offre : BLOQUE"
Write-Host "Creation enfants avant validation : NON"
Write-Host "Paiement automatique : NON"
Write-Host "======================================"
Write-Host ""
